-- Import every reviewed START23 v0.1 source workout as an athlete-selected
-- alternative. Swim rows remain distance-driven; this migration never infers a
-- planned duration from distance or pace.

alter table public.workout_templates
  drop constraint workout_templates_duration_minutes_check,
  alter column duration_minutes drop not null,
  add constraint workout_templates_duration_minutes_positive check (
    duration_minutes is null or duration_minutes > 0
  ),
  add constraint workout_templates_measure_present check (
    duration_minutes is not null
    or (discipline = 'swim' and distance_meters is not null)
  ),
  add column source_catalog text,
  add column source_workout_id text,
  add column athlete_selection_only boolean not null default false,
  add constraint workout_templates_source_reference_complete check (
    (source_catalog is null) = (source_workout_id is null)
  ),
  add constraint workout_templates_source_catalog_valid check (
    source_catalog is null or source_catalog = 'start23-v0.1'
  ),
  add constraint workout_templates_source_workout_id_valid check (
    source_workout_id is null
    or source_workout_id ~ '^(BIK|RUN|SWI)-[0-9]{3}$'
  );

alter table public.workout_segments
  drop constraint workout_segments_duration_minutes_check,
  alter column duration_minutes drop not null,
  add constraint workout_segments_duration_minutes_positive check (
    duration_minutes is null or duration_minutes > 0
  ),
  add constraint workout_segments_measure_present check (
    duration_minutes is not null or distance_meters is not null
  );

alter table public.planned_workouts
  drop constraint planned_workouts_duration_positive,
  alter column duration_minutes drop not null,
  add constraint planned_workouts_duration_positive check (
    duration_minutes is null or duration_minutes > 0
  ),
  add constraint planned_workouts_measure_present check (
    duration_minutes is not null
    or (discipline = 'swim' and distance_meters is not null)
  );

create unique index workout_templates_source_reference_unique
on public.workout_templates (source_catalog, source_workout_id)
where source_catalog is not null;

alter table private.workout_template_loads
  drop constraint workout_template_loads_calculation_method_check,
  add constraint workout_template_loads_calculation_method_check check (
    calculation_method in (
      'expected_rpe_midpoint_times_duration_hours',
      'source_catalog_predefined_tss'
    )
  );

create or replace function private.validate_workout_template(p_template_id uuid)
returns void
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_template public.workout_templates%rowtype;
  v_duration numeric;
  v_distance integer;
  v_segment_count integer;
  v_timed_segment_count integer;
  v_low_duration numeric;
  v_high_duration numeric;
begin
  select * into strict v_template
  from public.workout_templates
  where id = p_template_id;

  select
    count(*),
    count(duration_minutes),
    sum(duration_minutes),
    sum(coalesce(distance_meters, 0)),
    sum(duration_minutes) filter (
      where is_swim_technique
         or zone_number in (1, 2)
         or protocol_target ->> 'intensity_bucket' = 'low'
    ),
    sum(duration_minutes) filter (
      where not is_swim_technique
        and (
          zone_number in (3, 4, 5)
          or protocol_target ->> 'intensity_bucket' = 'high'
        )
    )
  into
    v_segment_count,
    v_timed_segment_count,
    v_duration,
    v_distance,
    v_low_duration,
    v_high_duration
  from public.workout_segments
  where template_id = p_template_id;

  if v_segment_count = 0
    or (v_template.duration_minutes is null and v_timed_segment_count <> 0)
    or (
      v_template.duration_minutes is not null
      and (
        v_timed_segment_count <> v_segment_count
        or v_duration is distinct from v_template.duration_minutes
      )
    )
    or coalesce(v_distance, 0) <> coalesce(v_template.distance_meters, 0)
    or exists (
      select 1
      from generate_series(1, v_segment_count) expected(sequence)
      left join public.workout_segments segment
        on segment.template_id = p_template_id
       and segment.sequence = expected.sequence
      where segment.sequence is null
    )
    or exists (
      select 1 from public.workout_segments
      where template_id = p_template_id
        and expected_rpe not between
          v_template.expected_rpe_min and v_template.expected_rpe_max
    )
    or (
      v_template.discipline <> 'swim'
      and exists (
        select 1 from public.workout_segments
        where template_id = p_template_id and is_swim_technique
      )
    )
    or (
      v_template.source_catalog is null
      and (
        case
          when coalesce(v_high_duration, 0) >= coalesce(v_low_duration, 0)
            and coalesce(v_high_duration, 0) > 0 then 'high'
          when coalesce(v_low_duration, 0) > coalesce(v_high_duration, 0) then 'low'
          else 'unresolved'
        end
      ) <> v_template.intensity_bucket
    )
    or not exists (
      select 1 from public.workout_template_phase_tags
      where template_id = p_template_id
    )
    or not exists (
      select 1 from private.workout_template_loads
      where template_id = p_template_id
    )
    or (
      v_template.fallback_compatibility = 'compatible'
      and exists (
        select 1 from public.workout_template_zone_requirements
        where template_id = p_template_id and requirement <> 'heart_rate'
      )
    )
  then
    raise exception 'workout template % is incomplete or inconsistent', p_template_id
      using errcode = '23514';
  end if;
end;
$$;

revoke all on function private.validate_workout_template(uuid)
from public, anon, authenticated, service_role;

