insert into public.workout_templates (
  id, template_key, version, discipline, name, description, duration_minutes,
  distance_meters, intensity_bucket, expected_rpe_min, expected_rpe_max,
  fallback_compatibility, source_catalog, source_workout_id, athlete_selection_only
)
select
  id, template_key, version, discipline, name, description, duration_minutes,
  distance_meters, intensity_bucket, expected_rpe_min, expected_rpe_max,
  'compatible', 'start23-v0.1', source_workout_id, true
from start23_source_catalog_import;

insert into public.workout_segments (
  template_id, sequence, name, instructions, duration_minutes, distance_meters,
  zone_number, expected_rpe, is_swim_technique
)
select
  source.id, segment.sequence, segment.name, segment.instructions,
  segment.duration_minutes, segment.distance_meters, segment.zone_number,
  segment.expected_rpe, false
from start23_source_catalog_import source
cross join lateral jsonb_to_recordset(source.segments) as segment (
  sequence integer,
  name text,
  instructions text,
  duration_minutes numeric,
  distance_meters integer,
  zone_number smallint,
  expected_rpe smallint
);

insert into public.workout_template_phase_tags (template_id, phase)
select id, phase
from start23_source_catalog_import
cross join lateral unnest(
  case
    when intensity_bucket = 'low'
      then array['base', 'build', 'recovery']::text[]
    else array['base', 'build']::text[]
  end
) as phases(phase);

insert into private.workout_template_loads (
  template_id, planned_tss, calculation_method, ruleset_version
)
select
  id, planned_tss, 'source_catalog_predefined_tss', 'start23-source-catalog-v0.1'
from start23_source_catalog_import;

do $$
declare
  v_template_id uuid;
begin
  for v_template_id in
    select id from start23_source_catalog_import order by source_workout_id
  loop
    perform private.validate_workout_template(v_template_id);
  end loop;
end;
$$;

drop table start23_source_catalog_import;

drop function public.get_workout_catalog_for_planning();

create function public.get_workout_catalog_for_planning()
returns table (
  id uuid,
  template_key uuid,
  version integer,
  discipline text,
  name text,
  description text,
  duration_minutes numeric,
  distance_meters integer,
  intensity_bucket text,
  expected_rpe_min smallint,
  expected_rpe_max smallint,
  fallback_compatibility text,
  explicit_scheduling_only boolean,
  athlete_selection_only boolean,
  source_catalog text,
  source_workout_id text,
  training_phases text[],
  zone_requirements text[],
  segments jsonb,
  planned_tss numeric,
  calculation_method text,
  ruleset_version text
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if coalesce((select auth.jwt() ->> 'role'), '') <> 'service_role' then
    raise exception 'trusted backend authorization required' using errcode = '42501';
  end if;
  return query
  select
    template.id,
    template.template_key,
    template.version,
    template.discipline,
    template.name,
    template.description,
    template.duration_minutes,
    template.distance_meters,
    template.intensity_bucket,
    template.expected_rpe_min,
    template.expected_rpe_max,
    template.fallback_compatibility,
    template.explicit_scheduling_only,
    template.athlete_selection_only,
    template.source_catalog,
    template.source_workout_id,
    array(
      select tag.phase
      from public.workout_template_phase_tags tag
      where tag.template_id = template.id
      order by tag.phase
    ),
    array(
      select requirement.requirement
      from public.workout_template_zone_requirements requirement
      where requirement.template_id = template.id
      order by requirement.requirement
    ),
    (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'sequence', segment.sequence,
            'name', segment.name,
            'instructions', segment.instructions,
            'duration_minutes', segment.duration_minutes,
            'distance_meters', segment.distance_meters,
            'zone_target', segment.zone_number,
            'protocol_target', segment.protocol_target,
            'expected_rpe', segment.expected_rpe,
            'is_swim_technique', segment.is_swim_technique
          )
          order by segment.sequence
        ),
        '[]'::jsonb
      )
      from public.workout_segments segment
      where segment.template_id = template.id
    ),
    load.planned_tss,
    load.calculation_method,
    load.ruleset_version
  from public.workout_templates template
  join private.workout_template_loads load
    on load.template_id = template.id
  order by template.template_key, template.version;
end;
$$;

revoke all on function public.get_workout_catalog_for_planning()
from public, anon, authenticated, service_role;
grant execute on function public.get_workout_catalog_for_planning()
to service_role;
